css:
:scope{display:block;width:100%}.pw{--bg:#01111D;--tx:#EDE6D8;--lb:#BBAFA3;--rl:#C6A15B;--ol:#BBAFA3;--ph:#182727;--pt:#BBAFA3;background:var(--bg);color:var(--tx);font-family:var(--os-font-body);font-weight:400}.pw[data-ground="bone"]{--bg:#E0D9CB;--tx:#01111D;--lb:#5E3A3C;--rl:#8C5B46;--ol:#01111D;--ph:#BBAFA3;--pt:#01111D}.pw[data-ground="sand"]{--bg:#BBAFA3;--tx:#01111D;--lb:#5E3A3C;--rl:#01111D;--ol:#01111D;--ph:#E0D9CB;--pt:#01111D}.pw[data-ground="olive"]{--bg:#182727;--ph:#01111D}.pw[data-ground="oxblood"]{--bg:#321013;--ph:#5E3A3C;--pt:#EDE6D8}.pw[data-ground="umber"]{--bg:#5E3A3C;--rl:#BBAFA3;--ph:#321013;--pt:#EDE6D8}.pw[data-ground="clay"]{--bg:#8C5B46;--lb:#EDE6D8;--rl:#EDE6D8;--ol:#EDE6D8;--ph:#5E3A3C;--pt:#EDE6D8}.pw[data-ground="sage"]{--bg:#7B8680;--tx:#01111D;--lb:#01111D;--rl:#01111D;--ol:#01111D;--ph:#BBAFA3;--pt:#01111D}
.pw__in{box-sizing:content-box;max-width:1200px;margin:0 auto;padding:128px 32px;display:flex;flex-wrap:wrap;gap:72px;align-items:flex-start}
.pw__pic{flex:1 1 360px;min-width:0;height:540px;overflow:hidden;line-height:0}.pw__pic img{display:block;width:100%;height:100%;object-fit:cover}
.pw__ph{background:var(--ph);display:flex;align-items:center;justify-content:center;text-align:center;font-family:var(--os-font-label);font-size:12px;letter-spacing:.24em;color:var(--pt);line-height:normal;padding:24px;box-sizing:border-box}
.pw__tx{flex:999 1 460px;min-width:0}
.pw__kicker{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.32em;text-transform:uppercase;color:var(--lb)}
.pw__rule{width:64px;height:1px;background:var(--rl);margin:28px 0 32px}
.pw__tx>.pw__rule:first-child{margin-top:0}
.pw__h2{margin:0;font-family:var(--os-font-heading);font-weight:500;font-size:60px;line-height:1.05;color:var(--tx)}
.pw__ps p{margin:18px 0 0;font-size:21px;line-height:1.55}.pw__ps p:first-child{margin-top:24px;font-family:var(--os-font-heading);font-style:italic;font-weight:500;font-size:28px;line-height:1.3}
.pw__nl{margin:40px 0 0;font-family:var(--os-font-label);font-size:12px;letter-spacing:.3em;text-transform:uppercase;color:var(--lb)}
.pw__names{margin:12px 0 0;font-size:19px;line-height:1.6;color:var(--lb)}
.pw__names span+span::before{content:"\00b7";margin:0 .5em}
.pw__btns{display:flex;flex-wrap:wrap;gap:16px;margin-top:40px}
.pw__btn{display:inline-block;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.22em;text-transform:uppercase;text-decoration:none;line-height:normal;color:var(--tx);border:1px solid var(--ol);padding:16px 24px}
.pw__btn:focus-visible{outline:2px solid var(--tx);outline-offset:3px}
@media (max-width:767px){.pw__in{padding:64px 20px;gap:36px}.pw__pic{flex-basis:100%;height:420px}.pw__tx{flex-basis:100%}.pw__rule{width:48px;margin:24px 0}.pw__h2{font-size:44px}.pw__ps p{font-size:19px}.pw__ps p:first-child{font-size:24px}.pw__nl{font-size:12px;letter-spacing:.24em}.pw__names{font-size:18px}.pw__btns{flex-direction:column}.pw__btn{text-align:center}}
